// Package config renders FactorioServer settings into the JSON files read by
// the Factorio server.
package config

import (
	"encoding/json"
	"fmt"

	apiextensionsv1 "k8s.io/apiextensions-apiserver/pkg/apis/apiextensions/v1"

	gamesv1alpha1 "github.com/streamixs/factorio/apps/agent/api/v1alpha1"
)

// Names of the files generated by this package. They match the files Factorio
// reads from its config directory.
const (
	ServerSettingsFile = "server-settings.json"
	MapGenSettingsFile = "map-gen-settings.json"
	MapSettingsFile    = "map-settings.json"
)

// ServerSecretValues holds the secret material referenced by the server
// settings. The controller resolves the referenced Secret keys before
// rendering, so secret values never enter the custom resource.
type ServerSecretValues struct {
	GamePassword string
	Password     string
	Token        string
}

// render serialises settings and appends the trailing newline Factorio
// configuration files are expected to end with.
func render(settings map[string]any, raw *apiextensionsv1.JSON) ([]byte, error) {
	if err := mergeRaw(settings, raw); err != nil {
		return nil, err
	}

	data, err := json.MarshalIndent(settings, "", "  ")
	if err != nil {
		return nil, fmt.Errorf("marshal settings: %w", err)
	}

	return append(data, '\n'), nil
}

// mergeRaw adds the keys of raw to settings. A key already produced by a typed
// field is rejected rather than silently overwritten.
func mergeRaw(settings map[string]any, raw *apiextensionsv1.JSON) error {
	if raw == nil || len(raw.Raw) == 0 {
		return nil
	}

	var extra map[string]any
	if err := json.Unmarshal(raw.Raw, &extra); err != nil {
		return fmt.Errorf("parse raw settings: %w", err)
	}

	for key, value := range extra {
		if _, exists := settings[key]; exists {
			return fmt.Errorf("setting %q is defined both by a typed field and raw", key)
		}
		settings[key] = value
	}

	return nil
}

func setString(settings map[string]any, key string, value *string) {
	if value != nil {
		settings[key] = *value
	}
}

func setBool(settings map[string]any, key string, value *bool) {
	if value != nil {
		settings[key] = *value
	}
}

func setInt32(settings map[string]any, key string, value *int32) {
	if value != nil {
		settings[key] = *value
	}
}

func setInt64(settings map[string]any, key string, value *int64) {
	if value != nil {
		settings[key] = *value
	}
}

func setFloat64(settings map[string]any, key string, value *float64) {
	if value != nil {
		settings[key] = *value
	}
}

func setMapGenSize(settings map[string]any, key string, value *gamesv1alpha1.MapGenSize) {
	if value != nil {
		settings[key] = string(*value)
	}
}

func setAllowCommands(settings map[string]any, key string, value *gamesv1alpha1.AllowCommands) {
	if value != nil {
		settings[key] = string(*value)
	}
}
